def check_age(record):
    if not isinstance(record["age"], int):
        raise TypeError(f"{record['name']}: age must be int")
    if record["age"] < 0:
        raise ValueError(f"{record['name']}: age is negative")

records = [
    {"name": "Asha", "age": 30},
    {"name": "Ben", "age": -4},
    {"name": "Chen", "age": "x"},
    {"name": "Dev", "age": -1},
]
errors = []
for r in records:
    try:
        check_age(r)
    except (TypeError, ValueError) as exc:
        errors.append(exc)

try:
    raise ExceptionGroup("validation", errors)
except* ValueError as eg:
    print("value problems:", [str(e) for e in eg.exceptions])
except* TypeError as eg:
    print("type problems:", [str(e) for e in eg.exceptions])
